"""This module renders Astroid nodes as string"""
from typing import TYPE_CHECKING, List

if TYPE_CHECKING:
    from astroid.nodes.node_classes import (
        Match,
        MatchAs,
        MatchCase,
        MatchClass,
        MatchMapping,
        MatchOr,
