        We need this method since not all nodes have :attr:`lineno` set.
        """
        line = self.lineno
        _node: Optional[NodeNG] = self
        try:
            while line is None:
                _node = next(_node.get_children())
                line = _node.lineno
        except StopIteration:
            _node = self.parent
            while _node and line is None:
                line = _node.lineno
